func (this *Coinbaseexchange) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	listEp804 := <-this.PublicGetProducts(params)
	if listEp804.Err != nil {
		panic(listEp804.Err)
	}
	var response []any = listEp804.Value
	//
	//     [
	//         {
	//             "id": "BTCAUCTION-USD",
	//             "base_currency": "BTC",
	//             "quote_currency": "USD",
	//             "base_min_size": "0.000016",
	//             "base_max_size": "1500",
	//             "quote_increment": "0.01",
	//             "base_increment": "0.00000001",
	//             "display_name": "BTCAUCTION/USD",
	//             "min_market_funds": "1",
	//             "max_market_funds": "20000000",
	//             "margin_enabled": false,
	//             "fx_stablecoin": false,
	//             "max_slippage_percentage": "0.02000000",
	//             "post_only": false,
	//             "limit_only": false,
	//             "cancel_only": true,
	//             "trading_disabled": false,
	//             "status": "online",
	//             "status_message": '',
	//             "auction_mode": false
	//         },
	//         {
	//             "id": "BTC-USD",
	//             "base_currency": "BTC",
	//             "quote_currency": "USD",
	//             "base_min_size": "0.000016",
	//             "base_max_size": "1500",
	//             "quote_increment": "0.01",
	//             "base_increment": "0.00000001",
	//             "display_name": "BTC/USD",
	//             "min_market_funds": "1",
	//             "max_market_funds": "20000000",
	//             "margin_enabled": false,
	//             "fx_stablecoin": false,
	//             "max_slippage_percentage": "0.02000000",
	//             "post_only": false,
	//             "limit_only": false,
	//             "cancel_only": false,
	//             "trading_disabled": false,
	//             "status": "online",
	//             "status_message": '',
	//             "auction_mode": false
	//         }
	//     ]
	//
	var result []any = []any{}
	var rawMarkets []any = this.ToArray(response)
	for i := 0; i < len(rawMarkets); i++ {
		var market any = DerefScalar(rawMarkets[i])
		var id *string = this.SafeString(market, "id")
		var parts []string = strings.Split(*id, "-")
		var baseId *string = SafeStringPtr(parts[0])
		var quoteId *string = SafeStringPtr(func() any {
			if 1 >= 0 && 1 < len(parts) {
				return parts[1]
			}
			return nil
		}())
		// BTCAUCTION-USD vs BTC-USD conflict workaround, see the output sample above
		// const baseId = this.safeString (market, 'base_currency');
		// const quoteId = this.safeString (market, 'quote_currency');
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var status *string = this.SafeString(market, "status")
		result = append(result, this.Extend(this.Fees["trading"], map[string]any{
			"id":             id,
			"symbol":         *base + "/" + *quote,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         this.SafeBool(market, "margin_enabled"),
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         (status != nil && *status == "online"),
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.SafeNumber(market, "base_increment"),
				"price":  this.SafeNumber(market, "quote_increment"),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": nil,
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.SafeNumber(market, "min_market_funds"),
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		}))
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

