func (this *Coinbaseexchange) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	// level 1 - only the best bid and ask
	// level 2 - top 50 bids and asks (aggregated)
	// level 3 - full order book (non aggregated)
	var request map[string]any = map[string]any{
		"id":    this.MarketId(symbol),
		"level": 2,
	}

	r1 := <-this.PublicGetProductsIdBook(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "sequence":1924393896,
	//         "bids":[
	//             ["0.01825","24.34811287",2],
	//             ["0.01824","72.5463",3],
	//             ["0.01823","424.54298049",6],
	//         ],
	//         "asks":[
	//             ["0.01826","171.10414904",4],
	//             ["0.01827","22.60427028",1],
	//             ["0.01828","397.46018784",7],
	//         ]
	//     }
	//
	var orderbook map[string]any = this.ParseOrderBook(response, symbol)
	orderbook["nonce"] = this.SafeInteger(response, "sequence")

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(orderbook)}
	return nil
}
func (this *Coinbaseexchange) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// fetchTickers
	//
	//      [
	//         1639472400, // timestamp
	//         4.26, // low
	//         4.38, // high
	//         4.35, // open
	//         4.27 // close
	//      ]
	//
	// fetchTicker
	//
	//     publicGetProductsIdTicker
	//
	//     {
	//         "trade_id":843439,
	//         "price":"0.997999",
	//         "size":"80.29769",
	//         "time":"2020-01-28T02:13:33.012523Z",
	//         "bid":"0.997094",
	//         "ask":"0.998",
	//         "volume":"1903188.03750000"
	//     }
	//
	//     publicGetProductsIdStats
	//
	//     {
	//         "open": "34.19000000",
	//         "high": "95.70000000",
	//         "low": "7.06000000",
	//         "volume": "2.41000000"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = nil
	var bid *string = nil
	var ask *string = nil
	var last *string = nil
	var high *string = nil
	var low *string = nil
	var open *string = nil
	var volume *string = nil
	var symbol *string = this.SafeString(market, "symbol")
	if IsArray(ticker) {
		last = this.SafeString(ticker, 4)
	} else {
		timestamp = this.Parse8601(this.SafeString(ticker, "time"))
		bid = this.SafeString(ticker, "bid")
		ask = this.SafeString(ticker, "ask")
		high = this.SafeString(ticker, "high")
		low = this.SafeString(ticker, "low")
		open = this.SafeString(ticker, "open")
		last = this.SafeString2(ticker, "price", "last")
		volume = this.SafeString(ticker, "volume")
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          high,
		"low":           low,
		"bid":           bid,
		"bidVolume":     nil,
		"ask":           ask,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    volume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

/**
 * @method
 * @name coinbaseexchange#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getproduct
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinbaseexchange) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Coinbaseexchange) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var request map[string]any = map[string]any{}

	r1 := <-this.PublicGetProductsSparkLines(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         YYY-USD: [
	//             [
	//                 1639472400, // timestamp
	//                 4.26, // low
	//                 4.38, // high
	//                 4.35, // open
	//                 4.27 // close
	//             ],
	//             [
	//                 1639468800,
	//                 4.31,
	//                 4.45,
	//                 4.35,
	//                 4.35
	//             ],
	//         ]
	//     }
	//
	var result map[string]any = map[string]any{}
	var marketIds []string = nil
	if response != nil {
		marketIds = make([]string, 0, len(response))
		for objectKey := range response {
			marketIds = append(marketIds, objectKey)
		}
	}
	var delimiter string = "-"
	for i := 0; i < len(marketIds); i++ {
		var marketId string = marketIds[i]
		var entry []any = SafeListTyped(response, marketId)
		var first []any = SafeListTypedDefault(entry, 0, []any{})
		var market map[string]any = this.SafeMarket(marketId, nil, delimiter)
		var symbol *string = SafeStringPtr(market["symbol"])
		if symbol != nil {
			result[*symbol] = TickerToMap(this.ParseTicker(first, market))
		}
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.FilterByArrayTickers(result, "symbol", symbolsNormalized))}
	return nil
}

/**
 * @method
 * @name coinbaseexchange#fetchTicker
 * @see https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getproductticker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinbaseexchange) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinbaseexchange) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"id": market["id"],
	}
	// publicGetProductsIdTicker or publicGetProductsIdStats
	var method string = *this.SafeString(this.Options, "fetchTickerMethod", "publicGetProductsIdTicker")
	var response map[string]any = nil
	if method == "publicGetProductsIdStats" {

		r1 := <-this.PublicGetProductsIdStats(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {

		r2 := <-this.PublicGetProductsIdTicker(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}

	//
	// publicGetProductsIdTicker
	//
	//     {
	//         "trade_id":843439,
	//         "price":"0.997999",
	//         "size":"80.29769",
	//         "time":"2020-01-28T02:13:33.012523Z",
	//         "bid":"0.997094",
	//         "ask":"0.998",
	//         "volume":"1903188.03750000"
	//     }
	//
	// publicGetProductsIdStats
	//
	//     {
	//         "open": "34.19000000",
	//         "high": "95.70000000",
	//         "low": "7.06000000",
	//         "volume": "2.41000000"
	//     }
	//
	ch <- AsyncResult[Ticker]{Value: this.ParseTicker(response, market)}
	return nil
}
func (this *Coinbaseexchange) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	//     {
	//         "type": "match",
	//         "trade_id": 82047307,
	//         "maker_order_id": "0f358725-2134-435e-be11-753912a326e0",
	//         "taker_order_id": "252b7002-87a3-425c-ac73-f5b9e23f3caf",
	//         "order_id": "d50ec984-77a8-460a-b958-66f114b0de9b",
	//         "side": "sell",
	//         "size": "0.00513192",
	//         "price": "9314.78",
	//         "product_id": "BTC-USD",
	//         "profile_id": "6244401d-c078-40d9-b305-7ad3551bc3b0",
	//         "sequence": 12038915443,
	//         "time": "2020-01-31T20:03:41.158814Z"
	//         "created_at": "2014-11-07T22:19:28.578544Z",
	//         "liquidity": "T",
	//         "fee": "0.00025",
	//         "settled": true,
	//         "usd_volume": "0.0924556000000000",
	//         "user_id": "595eb864313c2b02ddf2937d"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.Parse8601(this.SafeString2(trade, "time", "created_at"))
	var marketId *string = this.SafeString(trade, "product_id")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "-")
	var feeRate *string = nil
	var takerOrMaker *string = nil
	var cost *string = nil
	var feeCurrencyId *string = this.SafeStringLower(marketResolved, "quoteId")
	if feeCurrencyId != nil {
		var costField string = *feeCurrencyId + "_value"
		cost = this.SafeString(trade, costField)
		var liquidity *string = this.SafeString(trade, "liquidity")
		if liquidity != nil {
			takerOrMaker = SafeStringPtr(func() string {
				if liquidity != nil && *liquidity == "T" {
					return "taker"
				}
				return "maker"
			}())
			feeRate = this.SafeString(marketResolved, takerOrMaker)
		}
	}
	var feeCost *string = this.SafeString2(trade, "fill_fees", "fee")
	var fee map[string]any = map[string]any{
		"cost":     feeCost,
		"currency": marketResolved["quote"],
		"rate":     feeRate,
	}
	var id *string = this.SafeString(trade, "trade_id")
	var rawSide *string = this.SafeString(trade, "side")
	var side string = "buy"
	if rawSide != nil && *rawSide == "buy" {
		side = "sell"
	}
	var orderId *string = this.SafeString(trade, "order_id")
	// Coinbase Pro returns inverted side to fetchMyTrades vs fetchTrades
	var makerOrderId *string = this.SafeString(trade, "maker_order_id")
	var takerOrderId *string = this.SafeString(trade, "taker_order_id")
	if (orderId != nil) || ((makerOrderId != nil) && (takerOrderId != nil)) {
		side = func() string {
			if rawSide != nil && *rawSide == "buy" {
				return "buy"
			}
			return "sell"
		}()
	}
	var price *string = this.SafeString(trade, "price")
	var amount *string = this.SafeString(trade, "size")
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	return this.SafeTrade(map[string]any{
		"id":           id,
		"order":        orderId,
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"type":         nil,
		"takerOrMaker": takerOrMaker,
		"side":         side,
		"price":        price,
		"amount":       amount,
		"fee":          fee,
		"cost":         cost,
	}, marketResolved)
}

