func (this *Coinbaseexchange) ParseLedgerEntry(item any, optionalArgs ...any) LedgerEntry {
	//  {
	//      "id": "12087495079",
	//      "amount": "-0.0100000000000000",
	//      "balance": "0.0645419900000000",
	//      "created_at": "2021-10-28T17:14:32.593168Z",
	//      "type": "transfer",
	//      "details": {
	//          "from": "2f74edf7-1440-4586-86dc-ae58c5693691",
	//          "profile_transfer_id": "3ef093ad-2482-40d1-8ede-2f89cff5099e",
	//          "to": "dda99503-4980-4b60-9549-0b770ee51336"
	//      }
	//  },
	//  {
	//     "id": "11740725774",
	//     "amount": "-1.7565669701255000",
	//     "balance": "0.0016490047745000",
	//     "created_at": "2021-10-22T03:47:34.764122Z",
	//     "type": "fee",
	//     "details": {
	//         "order_id": "ad06abf4-95ab-432a-a1d8-059ef572e296",
	//         "product_id": "ETH-DAI",
	//         "trade_id": "1740617"
	//     }
	//  }
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(item, "id")
	var amountString *string = this.SafeString(item, "amount")
	var direction string
	var afterString *string = this.SafeString(item, "balance")
	var beforeString *string = Precise.StringSub(afterString, amountString)
	if Precise.StringLt(amountString, "0") {
		direction = "out"
		amountString = Precise.StringAbs(amountString)
	} else {
		direction = "in"
	}
	var amount *float64 = this.ParseNumber(amountString)
	var after *float64 = this.ParseNumber(afterString)
	var before *float64 = this.ParseNumber(beforeString)
	var timestamp *int64 = this.Parse8601(this.SafeString(item, "created_at"))
	var typeVar *string = this.ParseLedgerEntryType(this.SafeString(item, "type"))
	var code *string = this.SafeCurrencyCode(nil, currency)
	var details map[string]any = SafeMapTyped(item, "details")
	var account *string = nil
	var referenceAccount *string = nil
	var referenceId *string = nil
	if typeVar != nil && *typeVar == "transfer" {
		account = this.SafeString(details, "from")
		referenceAccount = this.SafeString(details, "to")
		referenceId = this.SafeString(details, "profile_transfer_id")
	} else {
		referenceId = this.SafeString(details, "order_id")
	}
	var status string = "ok"
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               id,
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"direction":        direction,
		"account":          account,
		"referenceAccount": referenceAccount,
		"referenceId":      referenceId,
		"type":             typeVar,
		"currency":         code,
		"amount":           amount,
		"before":           before,
		"after":            after,
		"status":           status,
		"fee":              nil,
	}, currency)
}

